/**
 * Export the API base path the spec's server URL declares, and put it between
 * the configured base URL, the Sentry origin, and each operation's path.
 */
import { writeFileSync } from "node:fs";
import { replaceOnce, srcPath, update } from "../lib/generated-source.mjs";

export function emit({ apiBasePath }) {
  if (!apiBasePath) throw new Error("The spec declares no API base path");
  writeFileSync(srcPath("api-base-path.gen.ts"), [
    "// This file is auto-generated by scripts/generate-api-base-path.mjs.",
    "",
    "/**",
    " * The path every operation path is relative to, from the server URL in",
    " * Sentry's OpenAPI spec. Requests go to the Sentry origin, then this, then",
    " * the operation path.",
    " */",
    `export const API_BASE_PATH = ${JSON.stringify(apiBasePath)};`,
    "",
  ].join("\n"));

  update("client/utils.gen.ts", source => {
    source = replaceOnce(source,
      "import { getUrl } from '../core/utils.gen';",
      "import { API_BASE_PATH } from '../api-base-path.gen';\nimport { getUrl } from '../core/utils.gen';");
    return replaceOnce(source,
      "    baseUrl: options.baseUrl as string,\n",
      "    baseUrl: `${(options.baseUrl as string | undefined) ?? ''}${API_BASE_PATH}`,\n");
  });
}
